/**
 * transfer-vitality.js — Greenbottle's Vitality Network
 *
 * Listens for chat messages generated by the "Transfer Vitality" SF2e action.
 * When detected on the character assigned to the current user, it shows a UI
 * letting the player choose how many Vitality Network points to spend, then
 * deducts those points and triggers a healing roll via pf2e-toolbelt.
 *
 * Two UI styles (configurable in module settings):
 *   'chat'  — embeds an interactive card directly in the chat log
 *   'popup' — shows a Foundry Dialog popup
 *
 * The heal roll is handled by healing.js, which passes it to pf2e-toolbelt's
 * Target Helper so it auto-applies to whoever is targeted on the canvas.
 */

import { rollHealing } from '../healing.js';

export function registerTransferVitalityHooks() {

  // ── Detect Transfer Vitality action ────────────────────────────────────────
  // 'createChatMessage' fires on every client for every new message.
  // We filter to only the Transfer Vitality action slug, then check whether
  // the current user has this actor assigned — prevents duplicate prompts.
  Hooks.on('createChatMessage', async (message, options, userId) => {
    const item = message.item;

    // item.slug is the system identifier — more reliable than checking the name string.
    if (item?.slug === 'transfer-vitality') {
      const actor = message.actor;

      // Only show the spend prompt to the user who has this character assigned.
      // Every client runs this hook, so we bail out on all others.
      if (game.user.character?.id !== actor.id) return;
      
      const vitalityResource = actor.system.resources?.vitalityNetwork;

      if (!vitalityResource) {
        ui.notifications.warn('No Vitality Network resource found on this character.');
        return;
      }

      const currentPoints = vitalityResource.value || 0;
      const maxPoints = vitalityResource.max || 0;

      if (currentPoints === 0) {
        ui.notifications.warn('You have no Vitality Network points remaining!');
        return;
      }

      // Read which UI style the user prefers (set in module settings).
      const dialogStyle = game.settings.get('greenbottles-vitality-network', 'dialogStyle');

      // ── Chat card style ─────────────────────────────────────────────────
      // Creates a whispered chat card with a number input and a "Spend" button.
      // Button clicks are handled by the renderChatMessage hook further below.
      if (dialogStyle === 'chat') {
        await ChatMessage.create({
          user: game.user.id,
          speaker: ChatMessage.getSpeaker({actor: actor}),
          whisper: [game.user.id], // Only show to the user who has this character assigned
          content: `
            <div class="pf2e chat-card vitality-network-card">
              <header class="card-header flexrow">
                <img src="${actor.img}" width="36" height="36"/>
                <h3>Vitality Network</h3>
              </header>
              <div class="card-content">
                <p><strong>Available Points:</strong> ${currentPoints} / ${maxPoints}</p>
                <div class="form-group">
                  <label>Points to spend:</label>
                  <input 
                    type="number" 
                    class="vitality-points-input" 
                    data-actor-id="${actor.id}"
                    data-current="${currentPoints}"
                    data-max="${maxPoints}"
                    min="1" 
                    max="${currentPoints}" 
                    value="1"
                    style="width: 100%; margin: 0.5rem 0;"
                  />
                </div>
                <button class="spend-vitality-btn" data-actor-id="${actor.id}">
                  <i class="fas fa-check"></i> Spend Points
                </button>
              </div>
            </div>
          `,
          flags: {
            'greenbottles-vitality-network': {
              interactive: true
            }
          }
        });
      }
      // ── Popup dialog style ──────────────────────────────────────────────
      else {
        new Dialog({
          title: "Vitality Network",
          content: `
            <form>
              <div class="form-group">
                <label style="font-weight: bold; margin-bottom: 0.5rem; display: block;">
                  Available Points: ${currentPoints} / ${maxPoints}
                </label>
                <label style="margin-bottom: 0.25rem; display: block;">
                  How many points do you want to spend?
                </label>
                <input 
                  type="number" 
                  name="points" 
                  min="1" 
                  max="${currentPoints}" 
                  value="1" 
                  autofocus 
                  style="width: 100%;"
                />
              </div>
            </form>
          `,
          buttons: {
            spend: {
              icon: '<i class="fas fa-check"></i>',
              label: "Spend",
              callback: async (html) => {
                const points = parseInt(html.find('[name="points"]').val());
                
                if (points > 0 && points <= currentPoints) {
                  const newValue = currentPoints - points;

                  try {
                    await actor.updateResource('vitalityNetwork', newValue);
                    
                    ui.notifications.info(`Spent ${points} Vitality Network points. ${newValue} remaining.`);
                    
                    // Optionally post a spending summary to chat based on the visibility setting.
                    const showSpending = game.settings.get('greenbottles-vitality-network', 'showSpending');

                    if (showSpending !== 'none') {
                      // Build whisper list: who gets to see the spending summary message.
                      let whisperTo = null;
                      const gmUsers = game.users.filter(u => u.isGM).map(u => u.id);
                      const actorOwners = game.users.filter(u => actor.testUserPermission(u, "OWNER")).map(u => u.id);

                      switch (showSpending) {
                        case 'owner':     whisperTo = actorOwners; break;
                        case 'gm':        whisperTo = gmUsers; break;
                        case 'owner-gm':  whisperTo = [...new Set([...actorOwners, ...gmUsers])]; break;
                        case 'all':
                        default:          whisperTo = null; break; // Public
                      }
                      
                      const messageData = {
                        user: game.user.id,
                        speaker: ChatMessage.getSpeaker({actor: actor}),
                        content: `
                          <div class="pf2e chat-card">
                            <header class="card-header flexrow">
                              <img src="${actor.img}" width="36" height="36"/>
                              <h3>Vitality Network</h3>
                            </header>
                            <div class="card-content">
                              <p><strong>${actor.name}</strong> spent <strong>${points}</strong> Vitality Network points.</p>
                              <p>Remaining: <strong>${newValue}</strong> / ${maxPoints}</p>
                            </div>
                          </div>
                        `
                      };
                      
                      if (whisperTo) {
                        messageData.whisper = whisperTo;
                      }
                      
                      await ChatMessage.create(messageData);
                    }

                    await rollHealing(actor, points);

                  } catch (error) {
                    console.error("Update failed:", error);
                    ui.notifications.error("Failed to update Vitality Network points!");
                  }
                }
              }
            },
            cancel: {
              icon: '<i class="fas fa-times"></i>',
              label: "Cancel"
            }
          },
          default: "spend"
        }).render(true);
      }
    }
  });

  // ── Chat card button handler ──────────────────────────────────────────────
  // Reattaches the "Spend" button listener whenever a vitality card is rendered.
  // This covers both the initial render and reloads (e.g. refreshing the page).
  Hooks.on('renderChatMessage', (message, html) => {
    html.find('.spend-vitality-btn').click(async (event) => {
      const button = event.currentTarget;
      const actorId = button.dataset.actorId;
      const input = html.find('.vitality-points-input')[0];
      const points = parseInt(input.value);
      const currentPoints = parseInt(input.dataset.current);
      const maxPoints = parseInt(input.dataset.max);
      
      if (points > 0 && points <= currentPoints) {
        const actor = game.actors.get(actorId);
        const newValue = currentPoints - points;
        
        try {
          await actor.updateResource('vitalityNetwork', newValue);
          ui.notifications.info(`Spent ${points} Vitality Network points. ${newValue} remaining.`);
          
          // Replace the interactive card content with a plain confirmation summary.
          html.find('.card-content').html(`
            <p><strong>${actor.name}</strong> spent <strong>${points}</strong> Vitality Network points.</p>
            <p>Remaining: <strong>${newValue}</strong> / ${maxPoints}</p>
          `);

          await rollHealing(actor, points);

        } catch (error) {
          console.error("Update failed:", error);
          ui.notifications.error("Failed to update Vitality Network points!");
        }
      }
    });
  });
}
